import { useEffect, useState } from "react";
import { motion } from "motion/react";

const STEPS = [
  { time: "09:12", text: "Приняли машину, загнали на подъёмник №3", done: true },
  { time: "09:40", text: "Диагностика ходовой: люфт правого рычага", done: true },
  { time: "10:05", text: "Согласовали замену рычага, цена 4 800 ₽", done: true },
  { time: "11:30", text: "Замена выполнена, фото работ", done: true, photo: true },
  { time: "13:00", text: "Сход-развал, контрольная поездка", done: false },
];

export default function SignatureSection() {
  const [visible, setVisible] = useState(4);
  const [typing, setTyping] = useState(false);

  useEffect(() => {
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced) return;
    const t = setTimeout(() => setTyping(true), 1200);
    const v = setTimeout(() => {
      setTyping(false);
      setVisible(5);
    }, 2600);
    return () => {
      clearTimeout(t);
      clearTimeout(v);
    };
  }, []);

  return (
    <section className="w-full border-t border-line bg-background py-16">
      <div className="mx-auto max-w-md px-5">
        <p className="text-sm text-muted-foreground">Статус ремонта</p>
        <h2 className="mt-2 text-2xl font-semibold tracking-tight text-foreground">
          Этапы приходят в Telegram, звонить не нужно
        </h2>

        <div className="mt-8 rounded-2xl border border-line bg-surface-alt p-4">
          <div className="flex items-center gap-2 border-b border-line pb-3">
            <div className="h-8 w-8 rounded-full bg-accent text-accent-ink text-sm font-medium flex items-center justify-center">
              Г24
            </div>
            <div>
              <p className="text-sm font-medium text-foreground">Гараж 24</p>
              <p className="text-xs text-muted-foreground">мастер Дмитрий</p>
            </div>
          </div>

          <div className="mt-4 space-y-3">
            {STEPS.slice(0, visible).map((s, i) => (
              <motion.div
                key={s.time}
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.35, delay: i * 0.1 }}
                className="flex gap-3"
              >
                <span className="mt-1 text-xs tabular-nums text-muted-foreground">
                  {s.time}
                </span>
                <div className="flex-1 rounded-xl border border-line bg-background px-3 py-2">
                  <p className="text-sm text-foreground">{s.text}</p>
                  {s.photo && (
                    <div className="mt-2 h-20 rounded-lg border border-line bg-scrim/10 flex items-center justify-center">
                      <span className="text-xs text-muted-foreground">фото работ</span>
                    </div>
                  )}
                </div>
              </motion.div>
            ))}

            {typing && (
              <div className="flex gap-3">
                <span className="mt-1 text-xs tabular-nums text-muted-foreground">
                  {STEPS[visible - 1].time}
                </span>
                <div className="flex items-center gap-1 rounded-xl border border-line bg-background px-3 py-2">
                  <motion.span
                    animate={{ opacity: [0.2, 1, 0.2] }}
                    transition={{ duration: 1, repeat: Infinity }}
                    className="h-1.5 w-1.5 rounded-full bg-muted-foreground"
                  />
                  <motion.span
                    animate={{ opacity: [0.2, 1, 0.2] }}
                    transition={{ duration: 1, repeat: Infinity, delay: 0.2 }}
                    className="h-1.5 w-1.5 rounded-full bg-muted-foreground"
                  />
                  <motion.span
                    animate={{ opacity: [0.2, 1, 0.2] }}
                    transition={{ duration: 1, repeat: Infinity, delay: 0.4 }}
                    className="h-1.5 w-1.5 rounded-full bg-muted-foreground"
                  />
                </div>
              </div>
            )}
          </div>
        </div>

        <p className="mt-4 text-sm text-muted-foreground">
          Ремонт обычно за один день. Гарантия 12 месяцев на работы.
        </p>
      </div>
    </section>
  );
}

