import { useEffect, useState } from "react";
import { motion } from "motion/react";

type Msg = {
  time: string;
  text: string;
  mine?: boolean;
};

const MESSAGES: Msg[] = [
  { time: "09:12", text: "Киа Рио, стук спереди справа", mine: true },
  { time: "09:14", text: "Приняли. Подъёмник 3, мастер Дмитрий", mine: false },
  { time: "10:40", text: "Диагностика: стойка стабилизатора и втулки. Запчасти в наличии", mine: false },
  { time: "11:05", text: "Согласуйте работы за 4 300 ₽", mine: false },
  { time: "11:07", text: "Да, делаем", mine: true },
  { time: "14:20", text: "Заменили. Фото деталей отправляю", mine: false },
];

const STAGES = ["Приём", "Диагностика", "Работы", "Контроль", "Выдача"];

export default function MasterChat() {
  const [visible, setVisible] = useState(1);

  useEffect(() => {
    if (typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setVisible(MESSAGES.length);
      return;
    }
    const t = setInterval(() => {
      setVisible((v) => (v >= MESSAGES.length ? 1 : v + 1));
    }, 1600);
    return () => clearInterval(t);
  }, []);

  const currentStage = STAGES[Math.min(3, Math.floor((visible / MESSAGES.length) * STAGES.length))];

  return (
    <section className="border-t border-line bg-background px-4 py-14 sm:py-20">
      <div className="mx-auto max-w-5xl">
