import { motion, useReducedMotion } from "motion/react";

const ROASTS = [
  { date: "17.02", origin: "Эфиопия · Иргачеффе", price: "650 ₽" },
  { date: "17.02", origin: "Колумбия · Уила", price: "690 ₽" },
  { date: "14.02", origin: "Бразилия · Серрадо", price: "650 ₽" },
];

export default function SignatureSection() {
  const reduce = useReducedMotion();

  return (
    <section className="relative overflow-hidden border-t border-line bg-background px-6 py-20 sm:py-28">
      <div className="mx-auto max-w-5xl">
        <p className="text-sm tracking-wide text-scrim-foreground">
          Обжарка каждую неделю · дата на пачке
        </p>

        <div className="mt-10 grid gap-10 sm:grid-cols-3">
          {ROASTS.map((r, i) => (
            <article
              key={r.origin}
              className="relative flex flex-col justify-between border border-line bg-surface-alt p-6"
            >
              <div className="flex items-baseline justify-between">
                <span className="text-xs text-scrim-foreground">
                  {String(i + 1).padStart(2, "0")} / 06
                </span>
                <span className="text-xs text-scrim-foreground">250 г</span>
              </div>

              <div className="mt-16 overflow-hidden">
                <motion.p
                  initial={reduce ? { y: 0, opacity: 1 } : { y: "100%", opacity: 0 }}
                  whileInView={reduce ? undefined : { y: 0, opacity: 1 }}
                  viewport={{ once: true, margin: "-80px" }}
                  transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
                  className="text-5xl font-semibold tracking-tight text-foreground sm:text-6xl"
                >
                  {r.date}
                </motion.p>
              </div>

              <motion.div
                initial={reduce ? { opacity: 1 } : { opacity: 0 }}
                whileInView={reduce ? undefined : { opacity: 1 }}
                viewport={{ once: true, margin: "-80px" }}
                transition={{ duration: 0.6, delay: 0.35 }}
                className="mt-6 border-t border-line pt-4"
              >
                <p className="text-sm text-foreground">{r.origin}</p>
                <p className="mt-1 text-sm text-scrim-foreground">{r.price}</p>
              </motion.div>
            </article>
          ))}
        </div>

        <p className="mt-10 text-sm text-scrim-foreground">
          Подписка раз в две недели — 1 290 ₽. Свежая пачка приезжает к дате обжарки.
        </p>
      </div>
    </section>
  );
}

