import { useEffect, useState } from "react";
import { m, LazyMotion, domAnimation, useReducedMotion } from "motion/react";

const ROAST_STEPS = [
  { min: 0, note: "Зелёное зерно Эфиопии загружается в ростер" },
  { min: 5, note: "Зерно желтеет, уходит влага" },
  { min: 9, note: "Первый крэк, зерно раскрывается" },
  { min: 12, note: "Выгрузка: на этой неделе 120 кг" },
];

export default function RoastTimer() {
  const [step, setStep] = useState(0);
  const reduced = useReducedMotion();

  useEffect(() => {
    if (reduced) return;
    const id = setInterval(() => setStep((s) => (s + 1) % ROAST_STEPS.length), 3200);
    return () => clearInterval(id);
  }, [reduced]);

  const current = ROAST_STEPS[step];

  return (
    <section className="bg-surface-alt text-foreground">
      <LazyMotion features={domAnimation}>
        <div className="mx-auto max-w-5xl px-5 py-16 md:py-24">
          <p className="font-mono text-xs uppercase tracking-[0.2em] text-primary">
            Обжарочный цех, Пермь
          </p>

          <div className="mt-6 grid items-end gap-10 md:grid-cols-[auto_1fr]">
            <div className="relative overflow-hidden">
              <div className="flex items-baseline gap-2 font-mono text-h1 leading-none tabular-nums">
                <m.span
                  key={`min-${current.min}`}
                  initial={reduced ? false : { y: "60%", opacity: 0 }}
                  animate={{ y: 0, opacity: 1 }}
                  transition={{ duration: 0.7, ease: [0.16, 1, 0.3, 1] }}
                  className="block"
                >
                  {String(current.min).padStart(2, "0")}
                </m.span>
                <span className="text-h4 text-foreground/50">мин</span>
              </div>
              <div className="mt-2 h-px w-full bg-line" />
              <m.p
                key={`note-${current.min}`}
                initial={reduced ? false : { opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: reduced ? 0 : 0.45, duration: 0.5 }}
                className="mt-3 font-mono text-sm text-foreground/70 md:text-base"
              >
                {current.note}
              </m.p>
            </div>

            <div className="max-w-md md:pb-2">
              <h2 className="text-h3 leading-tight">
                Каждую пятницу партия уходит из ростера на полку. Дата обжарки
                стоит на каждой пачке.
              </h2>
              <dl className="mt-6 space-y-2 border-t border-line pt-4 font-mono text-sm">
                <div className="flex justify-between">
                  <dt className="text-foreground/60">Сортов в ростере</dt>
                  <dd>6: Эфиопия, Колумбия, Бразилия</dd>
                </div>
                <div className="flex justify-between">
                  <dt className="text-foreground/60">Пачка 250 г</dt>
                  <dd>от 650 ₽</dd>
                </div>
                <div className="flex justify-between">
                  <dt className="text-foreground/60">Бариста</dt>
                  <dd>сертификация SCA, 3 точки</dd>
                </div>
              </dl>
            </div>
          </div>

          <div className="mt-10 grid grid-cols-4 gap-2 border-t border-line pt-4 md:hidden">
            {ROAST_STEPS.map((s, i) => (
              <p
                key={s.min}
                className={`font-mono text-xs tabular-nums ${
                  i === step ? "text-primary" : "text-foreground/40"
                }`}
              >
                {String(s.min).padStart(2, "0")}
              </p>
            ))}
          </div>
        </div>
      </LazyMotion>
    </section>
  );
}


